00%;\\r\\n    object-fit: cover;\\r\\n    aspect-ratio: 1\\/1;\\r\\n    background: #ffffff;\\r\\n    transition: transform 0.5s ease; \\/* Transisi zoom super mulus *\\/\\r\\n}\\r\\n.edd_download:hover .edd_download_image img {\\r\\n    transform: scale(1.15); \\/* Zoom in 15% *\\/\\r\\n}\\r\\n\\r\\n\\/* TOMBOL BELI *\\/\\r\\n.edd_download_buy_button {\\r\\n    margin-top: auto;\\r\\n}\\r\\n.edd_download_buy_button .edd-add-to-cart {\\r\\n    background: #e63946 !important;\\r\\n    color: #ffffff !important;\\r\\n    border-radius: 30px !important;\\r\\n    padding: 12px 24px !important;\\r\\n    font-weight: bold !important;\\r\\n    border: none !important;\\r\\n    width: 100% !important;\\r\\n    text-transform: uppercase;\\r\\n    transition: 0.3s;\\r\\n}\\r\\n.edd_download_buy_button .edd-add-to-cart:hover {\\r\\n    background: #ff4d5a !important;\\r\\n    transform: scale(1.05); \\/* Tombol membesar dikit *\\/\\r\\n}\\r\\n<\\/style>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"6926b0b\",\"elType\":\"container\",\"settings\":{\"background_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":\"\"},\"boxed_width\":{\"unit\":\"px\",\"size\":\"1200\",\"sizes\":[]},\"background_overlay_background\":\"classic\",\"background_overlay_attachment\":\"scroll\",\"background_overlay_repeat\":\"no-repeat\",\"background_overlay_size\":\"cover\",\"flex_gap\":{\"size\":0,\"column\":\"0\",\"row\":\"0\",\"unit\":\"px\",\"isLinked\":true},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"60\",\"right\":\"30\",\"bottom\":\"60\",\"left\":\"30\",\"isLinked\":false},\"__globals__\":{\"background_color\":\"globals\\/colors?id=astglobalcolor4\"},\"flex_direction\":\"row\",\"flex_align_items\":\"stretch\"},\"elements\":[{\"id\":\"c7c9c99\",\"elType\":\"container\",\"settings\":{\"_column_size\":\"100\",\"flex_gap\":{\"size\":0,\"column\":\"0\",\"row\":\"0\